package com.craftdistrict.block;

import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.block.state.properties.BlockStateProperties;
import net.minecraft.world.phys.AABB;
import net.minecraft.world.phys.shapes.Shapes;
import net.minecraft.world.phys.shapes.VoxelShape;

/** Generated by tools/generate_fire_interior.py; structural envelopes, part, facing. */
final class FireInteriorShapes {
    private static final VoxelShape[][][] SHAPES = {
        {
            rotations(Shapes.or(
                Block.box(0.5, 2.75, 14.625, 16, 14.25, 16)).optimize()),
            rotations(Shapes.or(
                Block.box(0, 2.75, 14.625, 15.5, 14.25, 16)).optimize())
        },
        {
            rotations(Shapes.or(
                Block.box(2, 1.5, 12.875, 14, 14.5, 16),
                Block.box(3.25, 3.25, 12, 12.75, 12.75, 12.875)).optimize())
        },
        {
            rotations(Shapes.or(
                Block.box(6.5, 0, 6.5, 9.5, 16, 9.5)).optimize())
        },
        {
            rotations(Shapes.or(
                Block.box(1, 0, 2.5, 12.25, 13.5, 14.5),
                Block.box(0.5, 13.5, 1, 16, 15, 15),
                Block.box(1, 11.75, 1.5, 16, 13.5, 2.5),
                Block.box(12, 10.5, 13, 16, 11.5, 14.25),
                Block.box(1.25, 15, 6.75, 14.75, 24.5, 14.75)).optimize()),
            rotations(Shapes.or(
                Block.box(0, 13.5, 1, 16, 15, 15),
                Block.box(0, 11.75, 1.5, 16, 13.5, 2.5),
                Block.box(0, 10.5, 13, 16, 11.5, 14.25),
                Block.box(1, 15, 11.375, 15, 24.5, 14.5)).optimize()),
            rotations(Shapes.or(
                Block.box(3.75, 0, 2.5, 15, 13.5, 14.5),
                Block.box(0, 13.5, 1, 15.5, 15, 15),
                Block.box(0, 11.75, 1.5, 15, 13.5, 2.5),
                Block.box(0, 10.5, 13, 4, 11.5, 14.25),
                Block.box(1.25, 15, 6.75, 14.75, 24.5, 14.75)).optimize())
        }
    };
    private FireInteriorShapes() { }

    static VoxelShape get(int decoration, int part, BlockState state) {
        int turn = switch (state.getValue(BlockStateProperties.HORIZONTAL_FACING)) {
            case EAST -> 1;
            case SOUTH -> 2;
            case WEST -> 3;
            default -> 0;
        };
        return SHAPES[decoration][part][turn];
    }

    private static VoxelShape[] rotations(VoxelShape north) {
        VoxelShape[] result = new VoxelShape[4];
        result[0] = north;
        for (int turn = 1; turn < 4; turn++) {
            VoxelShape rotated = Shapes.empty();
            for (AABB box : result[turn - 1].toAabbs()) {
                rotated = Shapes.or(rotated, Shapes.box(1 - box.maxZ, box.minY, box.minX,
                        1 - box.minZ, box.maxY, box.maxX));
            }
            result[turn] = rotated.optimize();
        }
        return result;
    }
}
